import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Acciones y vista previa instantánea","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/actions-and-preview.md","filePath":"es-ES/user-guide/actions-and-preview.md","lastUpdated":1787992644000}'),i={name:"es-ES/user-guide/actions-and-preview.md"};function r(l,e,s,c,d,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="acciones-y-vista-previa-instantanea" tabindex="-1">Acciones y vista previa instantánea <a class="header-anchor" href="#acciones-y-vista-previa-instantanea" aria-label="Permalink to &quot;Acciones y vista previa instantánea&quot;">​</a></h1><p>Lertaro no solo localiza archivos a velocidades ultrarrápidas, sino que integra un completo sistema de acciones contextuales y un potente panel de vista previa instantánea, lo que te permite inspeccionar, gestionar y abrir archivos sin cambiar al Explorador de archivos.</p><h2 id="_1-menu-de-acciones-en-detalle" tabindex="-1">1. Menú de acciones en detalle <a class="header-anchor" href="#_1-menu-de-acciones-en-detalle" aria-label="Permalink to &quot;1. Menú de acciones en detalle&quot;">​</a></h2><p>Pulsa <code>Ctrl+O</code> o la flecha derecha <code>→</code> en cualquier resultado de búsqueda (archivo, carpeta, aplicación o elemento de plugin) para desplegar el menú de acciones contextuales.</p><h3 id="tabla-de-acciones-principales-integradas" tabindex="-1">Tabla de acciones principales integradas <a class="header-anchor" href="#tabla-de-acciones-principales-integradas" aria-label="Permalink to &quot;Tabla de acciones principales integradas&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Acción</th><th style="text-align:left;">Atajo predeterminado</th><th style="text-align:left;">Descripción</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Abrir</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Abre el elemento seleccionado o inicia la aplicación con el programa predeterminado del sistema.</td></tr><tr><td style="text-align:left;"><strong>Mostrar en Explorador</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">Abre la carpeta contenedora y selecciona el archivo en el Explorador de Windows.</td></tr><tr><td style="text-align:left;"><strong>Ejecutar como administrador</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">Inicia la aplicación seleccionada con privilegios de administrador elevados.</td></tr><tr><td style="text-align:left;"><strong>Copiar ruta completa</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">Copia la ruta absoluta (p. ej. <code>D:\\Projects\\app.exe</code>) al portapapeles.</td></tr><tr><td style="text-align:left;"><strong>Cortar / Copiar archivo</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">Coloca el archivo en el portapapeles, listo para pegarlo en el Explorador o cualquier carpeta.</td></tr><tr><td style="text-align:left;"><strong>Pegar en esta carpeta</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">Si el elemento seleccionado es una carpeta, pega los archivos del portapapeles en su interior.</td></tr><tr><td style="text-align:left;"><strong>Eliminar (Papelera de reciclaje)</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">Mueve el archivo o carpeta seleccionado a la Papelera de reciclaje de Windows de forma segura.</td></tr><tr><td style="text-align:left;"><strong>Eliminación permanente</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">Elimina permanentemente el elemento (solicita confirmación; no se puede recuperar).</td></tr><tr><td style="text-align:left;"><strong>Menú contextual de Windows</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Despliega el menú contextual nativo completo de Windows Explorer (incluyendo opciones de terceros y &quot;Enviar a&quot;).</td></tr></tbody></table><h3 id="interaccion-y-filtrado-en-el-menu-de-acciones" tabindex="-1">Interacción y filtrado en el Menú de acciones <a class="header-anchor" href="#interaccion-y-filtrado-en-el-menu-de-acciones" aria-label="Permalink to &quot;Interacción y filtrado en el Menú de acciones&quot;">​</a></h3><ul><li><strong>Escribir para filtrar</strong>: Al abrir el menú de acciones, escribe directamente para filtrar por nombre (p. ej., teclear <code>copy</code> reduce la lista a las acciones de copiado).</li><li><strong>Navegación jerárquica</strong>: En elementos con submenús (como &quot;Enviar a&quot;), pulsa <code>→</code> o <code>Enter</code> para entrar; pulsa <code>←</code> o <code>Backspace</code> (con el filtro vacío) para regresar al nivel superior.</li><li><strong>Cerrar menú</strong>: Pulsa <code>Escape</code> para cerrar el menú de acciones y regresar a la lista de búsqueda.</li></ul><h2 id="_2-caracteristicas-de-la-lista-de-la-ventana-principal" tabindex="-1">2. Características de la lista de la Ventana principal <a class="header-anchor" href="#_2-caracteristicas-de-la-lista-de-la-ventana-principal" aria-label="Permalink to &quot;2. Características de la lista de la Ventana principal&quot;">​</a></h2><p>La Ventana principal de búsqueda (<code>Ctrl+F</code>) está diseñada para la gestión masiva de archivos y la exploración profunda:</p><ul><li><strong>Doble clic en la columna Ruta</strong>: Hacer doble clic en la columna <strong>Nombre</strong> abre el archivo; hacer doble clic en la columna <strong>Ruta</strong> abre directamente la carpeta que lo contiene.</li><li><strong>Carga continua de resultados en streaming</strong>: Al escanear millones de elementos, los resultados se van añadiendo a la lista en tiempo real sin tener que esperar a que finalice el escaneo completo. Puedes interactuar con las filas al instante.</li><li><strong>Navegación en bucle</strong>: Pulsar <code>↑</code> en la primera fila salta al último elemento; pulsar <code>↓</code> en la última fila vuelve al primero.</li><li><strong>Arrastre y memoria de tamaño</strong>: Arrastra la barra superior para reubicar la ventana; las dimensiones ajustadas manualmente se recuerdan automáticamente entre sesiones.</li></ul><h2 id="_3-vista-previa-instantanea-con-quicklook" tabindex="-1">3. Vista previa instantánea con QuickLook <a class="header-anchor" href="#_3-vista-previa-instantanea-con-quicklook" aria-label="Permalink to &quot;3. Vista previa instantánea con QuickLook&quot;">​</a></h2><p>Pulsa <code>Alt+P</code> en cualquier resultado para abrir el panel lateral de vista previa acoplado junto a la ventana de búsqueda:</p><h3 id="formatos-admitidos-y-funciones-avanzadas" tabindex="-1">Formatos admitidos y funciones avanzadas <a class="header-anchor" href="#formatos-admitidos-y-funciones-avanzadas" aria-label="Permalink to &quot;Formatos admitidos y funciones avanzadas&quot;">​</a></h3><ul><li><strong>Imágenes y gráficos vectoriales</strong>: Renderizado nítido y escalado de JPG, PNG, GIF (reproducción animada automática), BMP, WebP, ICO, SVG y más.</li><li><strong>Documentos y resaltado de código</strong>: Resaltado y formato para TXT, Markdown, JSON, XML, YAML, C#, Python, JS, HTML, etc.</li><li><strong>Reproducción instantánea de audio y vídeo</strong>: Los archivos multimedia (MP4, MKV, AVI, MOV, WMV, MP3, WAV, FLAC, WMA) <strong>se reproducen automáticamente</strong> con una barra de control integrada que se adapta al tema (reproducir/pausa, barra de progreso, duración, silencio). Se detiene al instante al cambiar de elemento.</li><li><strong>Inspección de carpetas</strong>: Muestra hasta 30 elementos directos con iconos y tamaños, omitiendo archivos ocultos y del sistema.</li></ul><h3 id="ajuste-de-pantalla-y-gestion-de-ventanas-emergentes" tabindex="-1">Ajuste de pantalla y gestión de ventanas emergentes <a class="header-anchor" href="#ajuste-de-pantalla-y-gestion-de-ventanas-emergentes" aria-label="Permalink to &quot;Ajuste de pantalla y gestión de ventanas emergentes&quot;">​</a></h3><ul><li><strong>Ajuste automático de límites</strong>: Las dimensiones de la vista previa se pueden personalizar en <a href="./settings/general.html#vista-previa"><strong>Configuración → General → Vista previa</strong></a>; Lertaro garantiza que nunca sobrepase el área visible del monitor.</li><li><strong>Evitación de diálogos nativos</strong>: Al previsualizar documentos de Office protegidos con contraseña, Lertaro oculta temporalmente sus ventanas para que puedas introducir la contraseña sin bloqueos, restaurándose después con normalidad.</li><li><strong>Arrastrar desde la vista previa</strong>: La parte superior del panel sirve como origen de arrastre para llevar el archivo previsualizado directamente a editores, navegadores o chats.</li></ul><h2 id="_4-paneles-interactivos-y-texto-enriquecido-con-plugins" tabindex="-1">4. Paneles interactivos y texto enriquecido con plugins <a class="header-anchor" href="#_4-paneles-interactivos-y-texto-enriquecido-con-plugins" aria-label="Permalink to &quot;4. Paneles interactivos y texto enriquecido con plugins&quot;">​</a></h2><p>QuickLook también admite tarjetas interactivas proporcionadas por plugins:</p><ul><li><strong>Texto enriquecido adaptado al tema</strong>: Renderizado mediante WebView2 y controles nativos, adaptándose a temas oscuros y claros con tipografía de alto contraste y barras de desplazamiento sutiles.</li><li><strong>Tarjetas de plugins</strong>: Consultas de diccionarios MDict, pronóstico meteorológico, capturas web y depuración de APIs.</li></ul><h2 id="_5-puente-con-quicklook-de-terceros-opcional" tabindex="-1">5. Puente con QuickLook de terceros (Opcional) <a class="header-anchor" href="#_5-puente-con-quicklook-de-terceros-opcional" aria-label="Permalink to &quot;5. Puente con QuickLook de terceros (Opcional)&quot;">​</a></h2><p>Si utilizas la herramienta externa de código abierto <strong>QuickLook</strong> (<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">QL-Win/QuickLook en GitHub</a>), puedes activar el plugin <strong>Puente QuickLook</strong> en <a href="./settings/plugins.html"><strong>Configuración → Plugins</strong></a>.</p><ul><li><strong>Control de vista previa externa</strong>: Se conecta mediante canalizaciones con nombre locales para acoplar la ventana externa de QuickLook directamente junto a Lertaro.</li><li><strong>Alternativa automática</strong>: Si QuickLook externo no está ejecutándose, Lertaro recurre fluidamente a su motor de vista previa integrado.</li></ul><h2 id="_6-liberar-la-ocupacion-de-un-archivo" tabindex="-1">6. Liberar la ocupación de un archivo <a class="header-anchor" href="#_6-liberar-la-ocupacion-de-un-archivo" aria-label="Permalink to &quot;6. Liberar la ocupación de un archivo&quot;">​</a></h2><p>El plugin oficial <strong>Liberar ocupación de archivos</strong> añade una acción disponible al seleccionar un único archivo existente. Muestra los procesos que lo están utilizando, sus PID y las rutas de sus ejecutables, y les solicita que liberen el archivo. La acción no está disponible para carpetas, archivos inexistentes ni selecciones múltiples; el botón de solicitud también se desactiva cuando no se detecta ningún proceso. El diálogo usa el tema del anfitrión, permanece sobre la ventana de búsqueda y queda oculto en Alt+Tab, además de incluir actualización manual.</p>',25)])])}const m=a(i,[["render",r]]);export{g as __pageData,m as default};
